const LIMIT=1024*1024, ITERATIONS=600000;
const encode=new TextEncoder(),decode=new TextDecoder('utf-8',{fatal:true});
function base64(bytes){return btoa(Array.from(bytes,b=>String.fromCharCode(b)).join(''));}
function unbase64(value,max){if(typeof value!=='string'||value.length>max*2||!/^[A-Za-z0-9+/]*={0,2}$/.test(value))throw new Error('invalidSave');const raw=atob(value);if(raw.length>max)throw new Error('invalidSave');return Uint8Array.from(raw,c=>c.charCodeAt(0));}
async function key(password,salt){if(typeof password!=='string'||password.length<12||password.length>256)throw new Error('passwordShort');const material=await crypto.subtle.importKey('raw',encode.encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',hash:'SHA-256',salt,iterations:ITERATIONS},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);}
export async function sealCase(value,password){const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12));const content=encode.encode(JSON.stringify(value));if(content.length>LIMIT)throw new Error('invalidSave');const derived=await key(password,salt);const ciphertext=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:encode.encode('virasat:case:1')},derived,content);return JSON.stringify({format:'virasat-encrypted-case',version:1,kdf:'PBKDF2-SHA256',iterations:ITERATIONS,salt:base64(salt),iv:base64(iv),ciphertext:base64(new Uint8Array(ciphertext))});}
export async function openCase(text,password){if(text.length>LIMIT*2)throw new Error('invalidSave');let value;try{value=JSON.parse(text);}catch{throw new Error('invalidSave');}if(!['virasat-encrypted-case','sangyan-encrypted-case'].includes(value?.format)||value.version!==1||value.iterations!==ITERATIONS||value.kdf!=='PBKDF2-SHA256')throw new Error('invalidSave');const salt=unbase64(value.salt,16),iv=unbase64(value.iv,12),ciphertext=unbase64(value.ciphertext,LIMIT+16);if(salt.length!==16||iv.length!==12)throw new Error('invalidSave');const derived=await key(password,salt);try{const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv,additionalData:encode.encode(value.format==='sangyan-encrypted-case'?'sangyan:case:1':'virasat:case:1')},derived,ciphertext);return JSON.parse(decode.decode(plain));}catch{throw new Error('cannotUnlock');}}
export function download(content,name,type='application/json'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.hidden=true;document.body.append(a);try{a.click();}finally{a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}}
